import type { OrderSnapshot } from "../../domain/entities/order.js";
export const queryFindOrder = (snapshots:readonly OrderSnapshot[], parameters:Readonly<{"order_id":string}>) => {
  if(!Object.hasOwn(parameters,"order_id")) throw new TypeError("missing parameter:order_id");
  let selected = snapshots.map(snapshot=>snapshot.fields).filter(row=>(row["order_id"] === parameters["order_id"]));
  selected = [...selected].sort((a,b)=>a["order_id"] === b["order_id"] ? 0 : a["order_id"] < b["order_id"] ? -1 : 1);
  selected = selected.slice(0,1);
  return Object.freeze(selected.map(row=>Object.freeze({"order_id":row["order_id"],"status":row["status"]})));
};

import { ruleOrderIsValid } from "../rules/order-is-valid.js";
export interface OrderFields {
  readonly "order_id": string;
  readonly "status": string;
  readonly "internal_note": string;
}
const brand: unique symbol = Symbol("Order");
const snapshots = new WeakSet<object>();
export interface OrderSnapshot {
  readonly [brand]: true;
  readonly fields: OrderFields;
  readonly hash: () => string;
  readonly sameIdentity: (other: OrderSnapshot) => boolean;
}
type Result = Readonly<{ok:true; value:OrderSnapshot; failure_codes:readonly string[]}> | Readonly<{ok:false; value:null; failure_codes:readonly string[]}>;
type Validator = (fields:OrderFields) => boolean;
interface Factory {
  readonly create:(input:unknown)=>Result;
  readonly reconstruct:(input:unknown)=>Result;
  readonly transition:(previous:OrderSnapshot,input:unknown)=>Result;
  readonly extend:(validate:Validator)=>Factory;
}
const failure = (code:string):Result => Object.freeze({ok:false, value:null, failure_codes:Object.freeze([code])});
const identityKey = (fields:OrderFields):string => JSON.stringify([fields["order_id"]]);
const makeFactory = (extra:readonly Validator[]):Factory => {
  const construct = (input:unknown, previous?:OrderSnapshot):Result => {
    if (input === null || typeof input !== 'object' || Array.isArray(input)) return failure('INVALID_FIELDS');
    const descriptors = Object.getOwnPropertyDescriptors(input);
    if (Reflect.ownKeys(input).length !== 3 || !(typeof descriptors["order_id"]?.value === "string" && typeof descriptors["status"]?.value === "string" && typeof descriptors["internal_note"]?.value === "string") || Object.values(descriptors).some(d => !Object.hasOwn(d,'value'))) return failure('INVALID_FIELDS');
    const fields:OrderFields = Object.freeze({"order_id": descriptors["order_id"]!.value, "status": descriptors["status"]!.value, "internal_note": descriptors["internal_note"]!.value});
    // Every exposed construction route reaches the bound Rule before a snapshot exists.
    if (!ruleOrderIsValid(fields)) return failure("RULE_FAILED:commerce:order-is-valid");
    try { if (!extra.every(validate => validate(fields) === true)) return failure('EXTENSION_FAILED'); }
    catch { return failure('EXTENSION_FAILED'); }
    const key = identityKey(fields);
    if (previous !== undefined && (!snapshots.has(previous) || previous.hash() !== key)) return failure('IDENTITY_CHANGED');
    const value:OrderSnapshot = Object.freeze({[brand]:true as const, fields, hash:()=>key, sameIdentity:(other:OrderSnapshot)=>snapshots.has(other) && other.hash() === key});
    snapshots.add(value);
    return Object.freeze({ok:true, value, failure_codes:Object.freeze([])});
  };
  return Object.freeze({
    create:(input:unknown):Result=>construct(input),
    reconstruct:(input:unknown):Result=>construct(input),
    transition:(previous:OrderSnapshot,input:unknown):Result=>snapshots.has(previous) ? construct(input,previous) : failure('INVALID_PREVIOUS'),
    extend:(validate:Validator):Factory=>{if(typeof validate!=='function') throw new TypeError('validator must be callable'); return makeFactory(Object.freeze([...extra,validate]));},
  });
};
export const createOrderFactory = () => makeFactory(Object.freeze([]));
